var import_obsidian2 = require("obsidian");
var DocxTemplateSuggestModal = class extends import_obsidian2.SuggestModal {
  constructor(app, plugin, onChoose) {
    super(app);
    this.plugin = plugin;
    this.onChoose = onChoose;
    this.setPlaceholder("\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 .docx \u0448\u0430\u0431\u043B\u043E\u043D...");
    this.limit = 20;
  }
  getSuggestions(query) {
    const q = query.toLowerCase();
    return this.app.vault.getFiles().filter((f) => f.path.toLowerCase().endsWith(".docx")).filter((f) => !q || f.path.toLowerCase().includes(q));
  }
  renderSuggestion(file, el) {
    el.setText(file.path);
  }
  onChooseSuggestion(file) {
    this.onChoose(file.path);
  }
};
